// CBv2Contracts.swift
//
// FROZEN INTEGRATION CONTRACT for the ContinuousBatchingV2 engine.
//
// Every v2 workstream (core runtime, scheduler, paged backend, prefix cache,
// sampling, model adaptation, harness, provider bridge) compiles against the
// types and protocols in this file. Do NOT edit this file in a feature
// worktree — contract changes go through the integration branch only.
// (Integration reconciliation applied; each addition is recorded in
// docs/engine-v2/CONTRACT-DECISIONS.md.)
//
// Design invariants this contract encodes (see docs/engine-v2/ARCHITECTURE.md):
//  - No left padding, no shared batch frontier, no batch-wide trims. Every
//    sequence owns its KV state and its absolute position counter.
//  - Decode is rectangular [B, 1] (one token per running request), so decode
//    raggedness cannot exist. Prefill runs per request as [1, chunk] under a
//    shared token budget.
//  - Sliding-window semantics are enforced by per-sequence storage eviction
//    keyed to absolute positions (never by masks over shared buffers).
//  - Attention dispatch is owned by the KV layer object (AttendingKVCache),
//    so backends (per-request SDPA v1, paged Metal kernel v2) are swappable
//    without touching models or the scheduler.

import Foundation
import MLX

// MARK: - Request & sampling surface

public struct CBv2RequestID: Hashable, Sendable, CustomStringConvertible {
    public let raw: UInt64
    public init(_ raw: UInt64) { self.raw = raw }
    public var description: String { "cbv2-\(raw)" }
}

public struct CBv2SamplingParams: Sendable {
    public var temperature: Float
    public var topP: Float
    public var topK: Int
    public var minP: Float
    public var repetitionPenalty: Float
    public var repetitionContextSize: Int
    public var frequencyPenalty: Float
    public var presencePenalty: Float
    public var seed: UInt64?
    public var logitBias: [Int: Float]
    public var topLogprobs: Int

    public init(
        temperature: Float = 1.0, topP: Float = 1.0, topK: Int = 0, minP: Float = 0,
        repetitionPenalty: Float = 1.0, repetitionContextSize: Int = 64,
        frequencyPenalty: Float = 0, presencePenalty: Float = 0,
        seed: UInt64? = nil, logitBias: [Int: Float] = [:], topLogprobs: Int = 0
    ) {
        self.temperature = temperature
        self.topP = topP
        self.topK = topK
        self.minP = minP
        self.repetitionPenalty = repetitionPenalty
        self.repetitionContextSize = repetitionContextSize
        self.frequencyPenalty = frequencyPenalty
        self.presencePenalty = presencePenalty
        self.seed = seed
        self.logitBias = logitBias
        self.topLogprobs = topLogprobs
    }
}

public struct CBv2Request: Sendable {
    public var id: CBv2RequestID
    public var promptTokens: [Int]
    public var sampling: CBv2SamplingParams
    public var maxTokens: Int
    public var stopTokens: Set<Int>
    public var stopStrings: [String]
    public var priority: Int
    public var cacheSalt: String?
    public var prefixCacheEnabled: Bool
    public var prefixCacheReceiptID: CBv2RequestID?
    public var multimodal: CBv2MultimodalInput?
    public var tokenConstraint: (any CBv2TokenConstraint)?

    public init(
        id: CBv2RequestID, promptTokens: [Int], sampling: CBv2SamplingParams = .init(),
        maxTokens: Int, stopTokens: Set<Int> = [], stopStrings: [String] = [], priority: Int = 0,
        cacheSalt: String? = nil, prefixCacheEnabled: Bool = true,
        multimodal: CBv2MultimodalInput? = nil,
        prefixCacheReceiptID: CBv2RequestID? = nil,
        tokenConstraint: (any CBv2TokenConstraint)? = nil
    ) {
        self.id = id
        self.promptTokens = promptTokens
        self.sampling = sampling
        self.maxTokens = maxTokens
        self.stopTokens = stopTokens
        self.stopStrings = stopStrings
        self.priority = priority
        self.cacheSalt = cacheSalt
        self.prefixCacheEnabled = prefixCacheEnabled
        self.multimodal = multimodal
        self.prefixCacheReceiptID = prefixCacheReceiptID
        self.tokenConstraint = tokenConstraint
    }
}

// MARK: - Multimodal input (vision prefill; additive)

public struct CBv2ImageSpan: Sendable, Equatable {
    public var tokenOffset: Int
    public var length: Int
    public init(tokenOffset: Int, length: Int) {
        self.tokenOffset = tokenOffset
        self.length = length
    }
    var end: Int { tokenOffset + length }
}

public struct CBv2MultimodalInput: @unchecked Sendable {
    public var spans: [CBv2ImageSpan]
    public var embeddings: () throws -> [MLXArray]

    public init(spans: [CBv2ImageSpan], embeddings: @escaping () throws -> [MLXArray]) {
        self.spans = spans
        self.embeddings = embeddings
    }
}

public enum CBv2MultimodalError: Error, Equatable {
    case unsupportedModel(String)
    case unsupportedBackend(String)
    case invalidSpans(String)
    case spanTooLong(blockTokens: Int, maxBatchedTokensPerStep: Int)
    case embeddingMismatch(String)
}

// MARK: - Layer descriptions (model structure as data)

public struct CBv2LayerKind: Sendable, Equatable {
    public enum Attention: Sendable, Equatable {
        case full
        case slidingWindow(Int)
    }
    public var attention: Attention
    public var sharesKVWithLayer: Int?
    public var isBidirectional: Bool
    public var hasSinks: Bool
    public var headDim: Int
    public var kvHeads: Int
    public var queryHeads: Int

    public init(
        attention: Attention, sharesKVWithLayer: Int? = nil, hasSinks: Bool = false,
        isBidirectional: Bool = false,
        headDim: Int, kvHeads: Int, queryHeads: Int
    ) {
        self.attention = attention
        self.sharesKVWithLayer = sharesKVWithLayer
        self.hasSinks = hasSinks
        self.isBidirectional = isBidirectional
        self.headDim = headDim
        self.kvHeads = kvHeads
        self.queryHeads = queryHeads
    }
}

@inline(__always)
func cbv2LayerKindsAllowPrefixReuse(_ layerKinds: [CBv2LayerKind]) -> Bool {
    !layerKinds.contains(where: \.isBidirectional)
}

// MARK: - Per-sequence KV state

public protocol CBv2SequenceKV: AnyObject {
    var absoluteOffset: Int { get }
    var retainedCount: Int { get }
    func update(keys: MLXArray, values: MLXArray) -> (MLXArray, MLXArray)
    func snapshot() -> (keys: MLXArray, values: MLXArray, offset: Int)
    func rollback(_ n: Int)

    // MARK: Speculative (MTP) writes

    var supportsSpeculativeWrites: Bool { get }
    func beginSpeculativeWrite()
    func commitSpeculativeWrite()
    func fastForward(to offset: Int)
    var byteCount: Int { get }
}

extension CBv2SequenceKV {
    public func fastForward(to offset: Int) {
        preconditionFailure(
            "fastForward(to:) is only valid on windowed sequence KV (\(type(of: self)))")
    }

    public var supportsSpeculativeWrites: Bool { false }
    public func beginSpeculativeWrite() {}
    public func commitSpeculativeWrite() {}
}

public protocol CBv2DecodeRootCompactionCapableSequenceKV: CBv2SequenceKV {}

public protocol CBv2KVBackend: AnyObject {
    var prefixReuseBackend: CBv2PrefixReuseBackend { get }
    func makeSequenceState(layerKinds: [CBv2LayerKind], promptLength: Int, maxLength: Int)
        throws -> [CBv2SequenceKV?]
    func makeSequenceState(
        adopting prefix: [(keys: MLXArray, values: MLXArray, offset: Int)?],
        plan: CBv2PrefixReusePlan,
        layerKinds: [CBv2LayerKind], maxLength: Int
    ) throws -> [CBv2SequenceKV?]
    func release(_ state: [CBv2SequenceKV?])
    var bytesInUse: Int { get }
    var bytesCapacity: Int { get }
    func updateBytesCapacity(_ bytes: Int)
    var bytesReserved: Int { get }
    var requiresMaterializedSnapshots: Bool { get }
    var kvResidency: any CBv2KVResidencyPolicy { get }
}

extension CBv2KVBackend {
    public var prefixReuseBackend: CBv2PrefixReuseBackend { .unknown }
    public var bytesReserved: Int { bytesInUse }
    public var requiresMaterializedSnapshots: Bool { false }
    public var kvResidency: any CBv2KVResidencyPolicy { CBv2ContiguousKVResidency() }
    public func updateBytesCapacity(_ bytes: Int) {}
    public func makeSequenceState(
        adopting prefix: [(keys: MLXArray, values: MLXArray, offset: Int)?],
        plan: CBv2PrefixReusePlan,
        layerKinds: [CBv2LayerKind],
        maxLength: Int
    ) throws -> [CBv2SequenceKV?] {
        throw CBv2KVError.backendIneligible(
            reason: "backend \(type(of: self)) has no proven prefix-reuse implementation")
    }

    public func makeSequenceState(
        adopting prefix: [(keys: MLXArray, values: MLXArray, offset: Int)?],
        layerKinds: [CBv2LayerKind],
        maxLength: Int
    ) throws -> [CBv2SequenceKV?] {
        guard let adoptedOffset = prefix.compactMap({ $0?.offset }).first else {
            throw CBv2KVError.backendIneligible(reason: "prefix contains no owning full snapshot")
        }
        var exactBytes = 0
        for entry in prefix {
            guard let entry else { continue }
            guard entry.offset == adoptedOffset else {
                throw CBv2KVError.backendIneligible(reason: "non-uniform adopted prefix offsets")
            }
            let (entryBytes, entryOverflow) = entry.keys.nbytes.addingReportingOverflow(
                entry.values.nbytes)
            let (total, totalOverflow) = exactBytes.addingReportingOverflow(entryBytes)
            guard !entryOverflow, !totalOverflow else {
                throw CBv2KVError.backendIneligible(reason: "adopted prefix byte overflow")
            }
            exactBytes = total
        }
        let capability = CBv2PrefixReuseCapability.derive(
            layerKinds: layerKinds,
            backend: prefixReuseBackend)
        guard let plan = capability.compatibilityPlan(
            adoptedOffset: adoptedOffset,
            exactStagedFullKVBytes: exactBytes,
            maximumSequenceLength: maxLength)
        else {
            throw CBv2KVError.backendIneligible(
                reason:
                    capability.unsupportedReason?.rawValue
                    ?? "layout requires an explicit matched-boundary replay plan")
        }
        return try makeSequenceState(
            adopting: prefix,
            plan: plan,
            layerKinds: layerKinds,
            maxLength: maxLength)
    }
}

public enum CBv2KVError: Error {
    case capacityExhausted(needed: Int, available: Int)
    case backendIneligible(reason: String)
}

extension CBv2KVError {
    public static let capacityExhaustedFinishPrefix = "kv_capacity_exhausted: "
}

// MARK: - Attention dispatch (owned by the layer cache object)

public protocol CBv2AttendingLayerCache: AnyObject {
    var layerIndex: Int { get }
    var kind: CBv2LayerKind { get }
    var rows: [CBv2SequenceKV] { get }
    func setRows(_ rows: [CBv2SequenceKV])
    var positionOffsets: MLXArray { get }
    func updateAndAttend(
        queries: MLXArray, keys: MLXArray, values: MLXArray,
        scale: Float, sinks: MLXArray?
    ) -> MLXArray
    func attendBorrowing(
        source: CBv2AttendingLayerCache,
        queries: MLXArray, scale: Float, sinks: MLXArray?
    ) -> MLXArray
}

// MARK: - Scheduler plan (vLLM-V1 style: no phases)

public enum CBv2RequestStatus: Sendable, Equatable {
    case waiting
    case running        // numComputedTokens < numTokens ⇒ still prefilling
    case preempted
    case finished(CBv2FinishReason)
}

public enum CBv2FinishReason: Sendable, Equatable {
    case stop           // stop token or stop string
    case length         // maxTokens or context limit
    case cancelled
    case error(String)
    case terminal(cause: CBv2TerminalCause, message: String)
}

public struct CBv2StepPlan: Sendable {
    public var assignments: [(id: CBv2RequestID, numTokens: Int)]
    public var preemptions: [CBv2RequestID]
    public var speculationFallbacks: [CBv2RequestID: CBv2SpeculationFallback]
    public init(
        assignments: [(id: CBv2RequestID, numTokens: Int)] = [],
        preemptions: [CBv2RequestID] = [],
        speculationFallbacks: [CBv2RequestID: CBv2SpeculationFallback] = [:]
    ) {
        self.assignments = assignments
        self.preemptions = preemptions
        self.speculationFallbacks = speculationFallbacks
    }
}

public enum CBv2SpeculationFallback: Sendable, Equatable {
    case tokenBudget
    case kvHeadroom
}

public struct CBv2SchedulerConfig: Sendable {
    public var maxConcurrentRequests: Int
    public var maxBatchedTokensPerStep: Int
    public var prefillChunkSize: Int
    public var maxWaiting: Int
    public var enablePrefixCache: Bool
    public init(
        maxConcurrentRequests: Int = 4, maxBatchedTokensPerStep: Int = 2048,
        prefillChunkSize: Int = 512, maxWaiting: Int = 64,
        enablePrefixCache: Bool = false
    ) {
        self.maxConcurrentRequests = maxConcurrentRequests
        self.maxBatchedTokensPerStep = maxBatchedTokensPerStep
        self.prefillChunkSize = prefillChunkSize
        self.maxWaiting = maxWaiting
        self.enablePrefixCache = enablePrefixCache
    }
}

// MARK: - Engine events (provider/consumer surface)

public struct CBv2TokenLogprob: Sendable {
    public var token: Int
    public var logprob: Float
    public var topLogprobs: [(token: Int, logprob: Float)]
    public init(token: Int, logprob: Float, topLogprobs: [(token: Int, logprob: Float)] = []) {
        self.token = token
        self.logprob = logprob
        self.topLogprobs = topLogprobs
    }
}

public enum CBv2Event: Sendable {
    case delta(text: String, tokens: [Int], logprobs: [CBv2TokenLogprob]?)
    case finished(reason: CBv2FinishReason, usage: CBv2Usage)
}

public struct CBv2Usage: Sendable {
    public var promptTokens: Int
    public var completionTokens: Int
    public var prefixCacheOutcome: CBv2PrefixCacheOutcome
    public var prefixCacheMatchedTokens: Int
    public var prefixCachePrefillTokensSaved: Int
    public var prefixCacheStrategy: CBv2PrefixReuseStrategy?
    public var prefixCacheReplayTokens: Int
    public var prefixCacheBoundarySplits: Int
    public var prefixCacheHitTokens: Int
    public init(
        promptTokens: Int, completionTokens: Int, prefixCacheHitTokens: Int = 0,
        prefixCacheOutcome: CBv2PrefixCacheOutcome = .disabled,
        prefixCacheMatchedTokens: Int = 0,
        prefixCachePrefillTokensSaved: Int = 0,
        prefixCacheStrategy: CBv2PrefixReuseStrategy? = nil,
        prefixCacheReplayTokens: Int = 0,
        prefixCacheBoundarySplits: Int = 0
    ) {
        self.promptTokens = promptTokens
        self.completionTokens = completionTokens
        self.prefixCacheOutcome = prefixCacheOutcome
        self.prefixCacheMatchedTokens = prefixCacheMatchedTokens
        self.prefixCachePrefillTokensSaved = prefixCachePrefillTokensSaved
